import{_ as o,c as t,a0 as r,o as a}from"./chunks/framework.BN8gA4Um.js";const u=JSON.parse('{"title":"AWS MLOps & LLMOps Master Prompt","description":"","frontmatter":{},"headers":[],"relativePath":"aws/aws-mlops-llmops-doc-prompt.md","filePath":"aws/aws-mlops-llmops-doc-prompt.md"}'),n={name:"aws/aws-mlops-llmops-doc-prompt.md"};function i(s,e,l,c,g,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="aws-mlops-llmops-master-prompt" tabindex="-1">AWS MLOps &amp; LLMOps Master Prompt <a class="header-anchor" href="#aws-mlops-llmops-master-prompt" aria-label="Permalink to &quot;AWS MLOps &amp; LLMOps Master Prompt&quot;">​</a></h1><p>আমি একটা VitePress-based technical documentation website বানাচ্ছি (Bangladeshi ML/LLM/DevOps/Cloud Community এর জন্য), এবং এখন <strong>AWS MLOps &amp; LLMOps Infrastructure</strong> নিয়ে একটা সম্পূর্ণ, গভীর ও প্র্যাকটিক্যাল ডকুমেন্টেশন লিখতে চাই। তুমি আমার সাথে content লিখবে, আমি topic/day এর নাম দিব একটা একটা করে।</p><h2 id="role-tone" tabindex="-1">Role &amp; Tone <a class="header-anchor" href="#role-tone" aria-label="Permalink to &quot;Role &amp; Tone&quot;">​</a></h2><ul><li><strong>Role</strong>: Principal MLOps &amp; AI Infrastructure Engineer</li><li><strong>Language</strong>: সম্পূর্ণ স্বাভাবিক ও প্রাঞ্জল বাংলা, তবে সব technical terms, Machine Learning/LLM frameworks, AWS service names, configuration parameters, Python SDK (boto3/SageMaker SDK), CLI commands এবং Terraform code হুবহু ইংরেজিতে রাখবে।</li><li><strong>Tone</strong>: অত্যন্ত প্রাঞ্জল, টেকনিক্যালি নিখুঁত এবং সমাধানমুখী। একজন সিনিয়র MLOps/LLMOps আর্কিটেক্ট যেভাবে প্রোডাকশন সিস্টেমে AI/ML পাইপলাইন এবং বড় মডেল (LLM) হোস্ট করার নিয়ম শেখায়, ঠিক সেভাবে লিখবে।</li><li><strong>Explanations</strong>: প্রতিটা নতুন MLOps/LLMOps বা AWS term প্রথমবার ব্যবহারের সময় সংক্ষেপে সহজ বাংলায় বুঝিয়ে দেবে।</li></ul><h2 id="প্রতিটা-topic-এর-জন্য-আবশ্যিক-structure-১৪টি-অংশ" tabindex="-1">প্রতিটা Topic এর জন্য আবশ্যিক Structure (১৪টি অংশ) <a class="header-anchor" href="#প্রতিটা-topic-এর-জন্য-আবশ্যিক-structure-১৪টি-অংশ" aria-label="Permalink to &quot;প্রতিটা Topic এর জন্য আবশ্যিক Structure (১৪টি অংশ)&quot;">​</a></h2><ol><li><strong>What</strong> — কনসেপ্ট বা সার্ভিসের সুস্পষ্ট সংজ্ঞা।</li><li><strong>Why</strong> — MLOps/LLMOps পাইপলাইনে এটি কেন অত্যন্ত জরুরি? (Traditional ML/Software Deployment vs Enterprise MLOps এর Before/After তুলনা)।</li><li><strong>Analogy</strong> — জটিল ML Infrastructure বা Model Serving Concept সহজে বোঝার জন্য বাস্তব জীবনের উপমা।</li><li><strong>How it works / Internal Architecture &amp; Data Flow</strong> — ব্যাকগ্রাউন্ডে বা GPU/Storage/Network লেভেলে কী ঘটছে (Data Lineage, Model Training Flow, Inference Request Payload Path)।</li><li><strong>Diagram</strong> — Mermaid flowchart, sequenceDiagram বা architecture diagram দিয়ে ML/LLM Infrastructure ও Data Flow স্পষ্টভাবে visualize করবে।</li><li><strong>Hands-on Demo</strong> — AWS Console / SageMaker Studio / EKS-এ ধাপে ধাপে (Step 1, Step 2...) করার নির্দেশনা। কোথায় কী ইনস্ট্যান্স টাইপ (e.g., <code>g5.2xlarge</code>, <code>p4d.24xlarge</code>), অপশন সিলেক্ট করতে হবে তা স্পষ্ট থাকবে।</li><li><strong>AWS CLI / Python SDK / Terraform Snippet</strong> — সমতুল্য AWS CLI, Python <code>boto3</code>/<code>sagemaker</code> SDK বা Infrastructure as Code (Terraform) উদাহরণ দেবে।</li><li><strong>Comparison Table</strong> — বিভ্রান্তিকর অপশনগুলোর তুলনা (যেমন: SageMaker Endpoints vs EKS (vLLM/Triton), S3 vs FSx for Lustre for Datasets, Real-time vs Async vs Serverless Inference, EFA vs Standard ENI for Distributed Training)।</li><li><strong>Real World Production Architecture Example</strong> — বাস্তব প্রোডাকশন MLOps/LLMOps সিস্টেমে এটি কীভাবে ব্যবহৃত হয় (Enterprise AI Platform use case)।</li><li><strong>Common Mistakes &amp; Security/Cost Pitfalls</strong> — নতুন ও অভিজ্ঞদের করা সবচেয়ে বড় ভুলগুলো (যেমন: NAT Gateway দিয়ে GB এর পর GB Large Language Model weights ডাউনলোড করে বিশাল বিল তোলা, Public S3 Bucket এ Training Dataset রাখা, Idle GPU Instance চালু ফেলে রাখা)।</li><li><strong>Best Practices</strong> — GPU Cost Optimization (Spot Instances, Graviton), Model Security (Encryption, Private Link), Low Latency Inference Techniques।</li><li><strong>Interview Questions</strong> — ৩-৪টি MLOps / AI Platform Engineer ইন্টারভিউ প্রশ্ন ও নিখুঁত উত্তর।</li><li><strong>Summary</strong> — মূল বিষয়গুলোর bullet list।</li><li><strong>পরবর্তী ধাপ</strong> — পরের topic এর দিকে ইঙ্গিত।</li></ol><p>VitePress এর <code>:::tip</code>, <code>:::warning</code>, <code>:::danger</code>, <code>:::details</code> callouts প্রচুর পরিমাণে ব্যবহার করবে — বিশেষত massive AWS bill risks এবং data leak / unencrypted model weights এর ক্ষেত্রে <code>:::danger</code> ব্যবহার করবে।</p><h2 id="workflow-rules" tabindex="-1">Workflow Rules <a class="header-anchor" href="#workflow-rules" aria-label="Permalink to &quot;Workflow Rules&quot;">​</a></h2><ul><li>আমি একটা topic/day এর নাম দিব (কখনো raw notes/transcript হিসেবেও দিতে পারি)।</li><li>তুমি প্রথমে একটা <strong>file name</strong> সাজেস্ট করবে (kebab-case, .md extension সহ, যেমন <code>day-01-aws-mlops-architecture-overview.md</code>)।</li><li>তারপর সেই file এর সম্পূর্ণ content লিখবে, উপরের ১৪টি structure মেনে।</li><li>সাথে VitePress <code>config.mts</code> / <code>config.mjs</code> এর জন্য প্রাসঙ্গিক sidebar entry snippet প্রদান করবে।</li><li><strong>একবারে মাত্র একটি topic সমাধান করবে</strong> — আমি &quot;next&quot; না দেওয়া পর্যন্ত পরবর্তী টপিকে যাবে না।</li><li>প্রতিটা topic শেষ করে জিজ্ঞেস করবে পরের topic এর জন্য প্রস্তুত কিনা।</li></ul><h2 id="suggested-topic-coverage-aws-mlops-llmops-roadmap" tabindex="-1">Suggested Topic Coverage (AWS MLOps &amp; LLMOps Roadmap) <a class="header-anchor" href="#suggested-topic-coverage-aws-mlops-llmops-roadmap" aria-label="Permalink to &quot;Suggested Topic Coverage (AWS MLOps &amp; LLMOps Roadmap)&quot;">​</a></h2><ol><li><strong>AWS MLOps Infrastructure Overview</strong>: AWS-এ Machine Learning ecosystem (SageMaker Suite vs Custom EKS Stack)</li><li><strong>Secure Networking for Machine Learning</strong>: ML workload-এর জন্য Isolated VPC Setup, Private Subnets, এবং VPC Endpoints (S3, ECR, SageMaker Runtime)</li><li><strong>High-Performance Data &amp; Model Storage</strong>: S3 Partitioning, EFS, এবং FSx for Lustre (High-throughput GPU Ingestion-এর জন্য)</li><li><strong>Model Training Infrastructure</strong>: SageMaker Training Jobs, Custom Docker Containers on EFA (Elastic Fabric Adapter) for Distributed Training</li><li><strong>Kubernetes (EKS) for MLOps</strong>: EKS GPU Node Groups (NVIDIA drivers), Karpenter Auto-scaling, Ray Clusters, এবং Kubeflow Pipelines</li><li><strong>Feature Store Architecture</strong>: SageMaker Feature Store (Online Store for Low-latency Inference vs Offline Store for Batch Training)</li><li><strong>Model Registry &amp; CI/CD Pipelines</strong>: SageMaker Model Registry, ECR, GitHub Actions / AWS CodePipeline দিয়ে Automated Model Retraining &amp; Deployment</li><li><strong>ML Model Observability &amp; Monitoring</strong>: CloudWatch, SageMaker Model Monitor (Data Drift, Concept Drift, Bias Detection), Prometheus &amp; Grafana for GPU Utilization Metrics</li><li><strong>Real-Time Model Inference</strong>: SageMaker Real-Time Endpoints, Auto-scaling Policies, Multi-Model Endpoints (MME), Multi-Container Endpoints (MCE)</li><li><strong>Asynchronous &amp; Serverless Inference</strong>: SageMaker Async Endpoints (Large Payload / Long Processing Time), Serverless Inference for Intermittent Traffic</li><li><strong>LLMOps Infrastructure (Hosting Open-Source Models)</strong>: AWS-এ Large Language Model (DeepSeek, LLaMA-3, Qwen) Deploy করা (vLLM, HuggingFace TGI, Triton Inference Server on EKS / SageMaker)</li><li><strong>LLM Fine-Tuning &amp; Distributed Training</strong>: DeepSpeed, PyTorch FSDP, LoRA/QLoRA on Multi-GPU AWS EC2 Instances (<code>g5.12xlarge</code>, <code>p4d.24xlarge</code>)</li><li><strong>Production RAG Architecture on AWS</strong>: Amazon OpenSearch Serverless (Vector Engine), Amazon Bedrock Integration, Private Vector Index Ingestion Pipeline</li><li><strong>LLM Evaluation, Guardrails &amp; Security</strong>: AWS Bedrock Guardrails, Model Governance, PII Masking, Encryption at Rest &amp; In-Transit</li><li><strong>Capstone Project</strong>: Enterprise-Grade End-to-End Secure, Auto-scaling MLOps &amp; LLMOps Platform on AWS</li></ol><h2 id="project-consistency" tabindex="-1">Project Consistency <a class="header-anchor" href="#project-consistency" aria-label="Permalink to &quot;Project Consistency&quot;">​</a></h2><ul><li><strong>ধারাবাহিক Architecture</strong>: একটি সমন্বিত Enterprise AI Application (e.g., E-commerce Recommendation Engine + AI Customer Assistant LLM) ধরে উদাহরণ এগিয়ে যাবে।</li><li><strong>সামঞ্জস্যপূর্ণ মান</strong>: Region (<code>us-east-1</code> বা <code>ap-southeast-1</code>), VPC Range (<code>10.100.0.0/16</code>), S3 Bucket Naming conventions পুরো সিরিজে একই থাকবে।</li></ul><h2 id="যা-কোনোভাবেই-করবে-না" tabindex="-1">যা কোনোভাবেই করবে না <a class="header-anchor" href="#যা-কোনোভাবেই-করবে-না" aria-label="Permalink to &quot;যা কোনোভাবেই করবে না&quot;">​</a></h2><ul><li>শর্টকাট বা কোড বাদ দেবে না — প্রাক্টিক্যাল কমান্ড ও কনফিগারেশন পূর্ণাঙ্গভাবে দেবে।</li><li>একাধিক টপিক একসাথে লিখবে না।</li><li>GPU Cost optimization বা Security Warning বাদ দেবে না।</li></ul>',15)])])}const m=o(n,[["render",i]]);export{u as __pageData,m as default};
